```js
function isPalindrome(text) {
  let left = 0;
  let right = text.length - 1;
  while (left < right) {
    if (text[left] !== text[right]) return false;
    left++;
    right--;
  }
  return true;
}
```

This version compares the exact UTF-16 code units in the string.

```js
function pairWithSum(values, target) {
  let left = 0, right = values.length - 1;
  while (left < right) {
    const sum = values[left] + values[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;
    else right--;
  }
  return null;
}
```

The returned indices refer to the already sorted array.

```js
function removeDuplicates(values) {
  if (values.length === 0) return 0;
  let write = 0;
  for (let read = 1; read < values.length; read++) {
    if (values[read] !== values[write]) {
      values[++write] = values[read];
    }
  }
  return write + 1;
}
```

Only `values.slice(0, returnedLength)` is the compacted result.

```js
function moveZeros(values) {
  let write = 0;
  for (let read = 0; read < values.length; read++) {
    if (values[read] !== 0) {
      [values[write], values[read]] = [values[read], values[write]];
      write++;
    }
  }
  return values;
}
```

Explicit zero comparison preserves other falsy values.
